from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class BridgeAudit:
    derivability: bool
    pa_consistent: bool
    reflection: bool
    contradiction_proof_soundness: bool

    def evaluate(self) -> dict[str, bool]:
        positive = self.derivability and self.pa_consistent and self.reflection
        negative = self.derivability and self.contradiction_proof_soundness
        return {"positive_half": positive, "negative_half": negative,
                "independence": positive and negative}

if __name__ == '__main__':
    for x in [BridgeAudit(True,True,True,True), BridgeAudit(True,True,False,True), BridgeAudit(True,True,True,False)]: print(x.evaluate())

from __future__ import annotations
from itertools import product

def search_box_true_countermodels(indices: int) -> list[dict[str, bool]]:
    """Find valuations with false bottom and at least one true boxed contradiction."""
    witnesses: list[dict[str, bool]] = []
    for bottom, *boxes in product((False, True), repeat=indices + 1):
        if not bottom and any(boxes):
            row = {"bottom": bottom}
            row.update({f"box_{i}_bottom": value for i, value in enumerate(boxes)})
            witnesses.append(row)
    return witnesses

if __name__ == '__main__':
    print(search_box_true_countermodels(3)[:4])

